  Plaintext c0("c0");
  Plaintext c1("c1");
  Plaintext c2("c2");
  Plaintext c3("c3");
  Plaintext c4("c4");
  Plaintext c5("c5");
  Plaintext c6("c6");
  Plaintext c7("c7");

  // group A: (c1 - c7) T1   (level 2)
  Ciphertext A1 = z * c1;
  Ciphertext A2 = z * c7;
  Ciphertext A = A1 - A2;

  // group B: (c2 - c6) T2   (level 3)
  Ciphertext B1 = T2 * c2;
  Ciphertext B2 = T2 * c6;
  Ciphertext B = B1 - B2;

  // group C: (c3 - c5) T3   (level 4)
  Ciphertext C1 = T3 * c3;
  Ciphertext C2 = T3 * c5;
  Ciphertext C = C1 - C2;

  Ciphertext low = A + B;
  low = low + C;

  // q = c5 T1 + c6 T2 + c7 T3
  Ciphertext q1 = z * c5;
  Ciphertext q2 = T2 * c6;
  Ciphertext q3 = T3 * c7;
  Ciphertext q = q1 + q2;
  q = q + q3;

  // T4 * (2q + c4)  == 2 T4 q + c4 T4
  Ciphertext qq = q + q;
  qq = qq + c4;
  Ciphertext P = T4 * qq;

  Ciphertext result = P + low;
  result = result + c0;
  result.set_output("y");
}
```

The degree-7 kernel from attempt 3 is correct and is the fastest so far at 167.67 ms, against the 181.90 ms baseline. I'm keeping it as the final kernel.

